function IndexCard({ page }) {
  const meta = getPageMeta(page);
  const icon = ICON_SVG[meta.iconKey] || ICON_SVG.page;
  const href = `/wiki/${encodeWikiSlug(page.slug)}`;

  return (
    <Link href={href} style={{ textDecoration: 'none' }}>
      <div style={{
        background: 'var(--bg-card)',
        border: '1px solid var(--border-card)',
        borderRadius: '10px',
        padding: '18px 18px 16px',
        cursor: 'pointer',
        transition: 'border-color 0.15s, background 0.15s',
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        gap: '10px',
      }}
        onMouseEnter={e => {
          e.currentTarget.style.borderColor = 'var(--accent-dim)';
          e.currentTarget.style.background = 'var(--bg-hover)';
        }}
        onMouseLeave={e => {
          e.currentTarget.style.borderColor = 'var(--border-card)';
          e.currentTarget.style.background = 'var(--bg-card)';
        }}
      >
        {/* Icon row + spoilers badge */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
          <span style={{ color: 'var(--accent-2)' }}>{icon}</span>
          {page.spoilers && (
            <span style={{
              background: 'rgba(245, 158, 11, 0.12)',
              color: '#f59e0b',
              border: '1px solid rgba(245, 158, 11, 0.3)',
              borderRadius: '5px',
              fontSize: '10px',
              fontWeight: '600',
              padding: '2px 7px',
              letterSpacing: '0.03em',
            }}>
              Spoilers
            </span>
          )}
        </div>

        {/* Title + subtitle */}
        <div>
          <div style={{
            color: 'var(--text-1)',
            fontWeight: '600',
            fontSize: '14.5px',
            lineHeight: '1.3',
            marginBottom: '4px',
          }}>
            {page.title}
          </div>
          {meta.subtitle && (
            <div style={{ color: 'var(--text-5)', fontSize: '12px' }}>
              {meta.subtitle}
            </div>
          )}
        </div>
      </div>
    </Link>
  );
}

// ─── Row for all-pages list ───────────────────────────────────────────────────

function PageRow({ page, isLast }) {
  const href = `/wiki/${encodeWikiSlug(page.slug)}`;
  return (
    <Link href={href} style={{ textDecoration: 'none', display: 'block' }}>
      <div style={{
        padding: '12px 16px',
        borderBottom: isLast ? 'none' : '1px solid var(--border)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        transition: 'background 0.12s',
        cursor: 'pointer',
      }}
        onMouseEnter={e => { e.currentTarget.style.background = 'var(--bg-hover)'; }}
        onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
      >
        <div>
          <div style={{ color: 'var(--text-2)', fontSize: '13.5px', fontWeight: '500' }}>{page.title}</div>
          <div style={{ color: 'var(--text-7)', fontSize: '11.5px', marginTop: '2px' }}>{page.slug}</div>
        </div>
        <div style={{ display: 'flex', gap: '6px', flexShrink: 0, marginLeft: '12px' }}>
          {page.is_index && (
            <span style={{
              background: 'rgba(59,130,246,0.12)',
              color: 'var(--accent-2)',
              border: '1px solid rgba(59,130,246,0.25)',
              borderRadius: '5px',
              fontSize: '10px',
              fontWeight: '600',
              padding: '2px 7px',
            }}>Índice</span>
          )}
          {page.spoilers && (
            <span style={{
              background: 'rgba(245,158,11,0.12)',
              color: '#f59e0b',
              border: '1px solid rgba(245,158,11,0.25)',
              borderRadius: '5px',
              fontSize: '10px',
              fontWeight: '600',
              padding: '2px 7px',
            }}>Spoilers</span>
          )}
          {page.visibility === 'private' && (
            <span style={{
              background: 'rgba(239,68,68,0.12)',
              color: '#f87171',
              border: '1px solid rgba(239,68,68,0.25)',
              borderRadius: '5px',
              fontSize: '10px',
              fontWeight: '600',
              padding: '2px 7px',
            }}>Privado</span>
          )}
        </div>
      </div>
    </Link>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

export default function WikiIndex() {
  const [pages, setPages] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notesOpen, setNotesOpen] = useState(false);
  const [messagesOpen, setMessagesOpen] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const router = useRouter();

  useEffect(() => {
    const userData = localStorage.getItem('user');
    if (!userData) { router.push('/login'); return; }

    try {
      const parsedUser = JSON.parse(userData);
      setUser(parsedUser);

      fetch('/content/pages.json')
        .then(res => res.json())
        .then(data => {
          setPages(data);
          setLoading(false);
        })
        .catch(err => {
          setError(err.message);
          setLoading(false);
        });

      if (parsedUser.role !== 'admin') {
        loadUnreadCount(parsedUser.username);
      }
    } catch {
      router.push('/login');
    }
  }, [router]);

  const loadUnreadCount = async (username) => {
    try {
      const { data, error } = await supabase
        .from('dm_messages')
        .select('id')
        .eq('recipient_username', username)
        .eq('read', false);
      if (!error && data) setUnreadCount(data.length);
    } catch {}
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    router.push('/login');
  };

  // Loading / error screens (before layout is available)
  if (loading) {
    return (
      <div style={{ minHeight: '100vh', background: 'var(--bg)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ color: 'var(--accent-2)', fontSize: '16px' }}>Cargando...</div>
      </div>
    );
  }
  if (error) {
    return (
      <div style={{ minHeight: '100vh', background: 'var(--bg)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ color: '#f87171', fontSize: '16px' }}>Error: {error}</div>
      </div>
    );
  }
  if (!user) return null;

  // Filter by access
  const accessiblePages = pages.filter(page => {
    if (user.role === 'admin') return true;
    if (page.visibility === 'public') return true;
    if (page.allowed_users?.includes(user.username)) return true;
    return false;
  });

  const indexPages = accessiblePages.filter(p => p.is_index);
  const mainIndexPages = indexPages.filter(isMainIndexPage);

  const filteredPages = searchTerm
    ? accessiblePages.filter(p => p.title.toLowerCase().includes(searchTerm.toLowerCase()))
    : accessiblePages;

  return (
    <>
      <WikiLayout
        user={user}
        indexPages={indexPages}
        allPages={accessiblePages}
        searchTerm={searchTerm}
        onSearch={setSearchTerm}
        onLogout={handleLogout}
      >
        <div style={{ padding: '32px 36px', maxWidth: '1100px' }}>

          {/* Page header */}
          <div style={{ marginBottom: '28px' }}>
            <h1 style={{
              color: 'var(--text-1)',
              fontSize: '22px',
              fontWeight: '700',
              letterSpacing: '0.04em',
              textTransform: 'uppercase',
              fontVariant: 'small-caps',
              margin: 0,
              textAlign: 'left',
            }}>
              Páginas Índice
            </h1>
            <p style={{ color: 'var(--text-6)', fontSize: '13px', marginTop: '4px' }}>
              {accessiblePages.length} páginas en total · Archivo de las Tormentas
            </p>
          </div>

          {/* Index cards grid (hidden while searching) */}
          {!searchTerm && mainIndexPages.length > 0 && (
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(3, 1fr)',
              gap: '12px',
              marginBottom: '40px',
            }}>
              {mainIndexPages.map(page => (
                <IndexCard key={page.slug} page={page} />
              ))}
            </div>
          )}

          {/* All pages section */}
          <div>
            <div style={{
              display: 'flex',
              alignItems: 'baseline',
              gap: '8px',
              marginBottom: '12px',
            }}>
              <h2 style={{
                color: 'var(--text-5)',
                fontSize: '11px',
                fontWeight: '700',
                letterSpacing: '0.12em',
                textTransform: 'uppercase',
                margin: 0,
                textAlign: 'left',
              }}>
                {searchTerm ? 'Resultados de búsqueda' : 'Todas las páginas'}
              </h2>
              <span style={{ color: 'var(--text-6)', fontSize: '11px' }}>({filteredPages.length})</span>
            </div>

            <div style={{
              background: 'var(--bg-card)',
              border: '1px solid var(--border-card)',
              borderRadius: '10px',
              overflow: 'hidden',
            }}>
              {filteredPages.length === 0 ? (
                <div style={{ padding: '32px', textAlign: 'center', color: 'var(--text-6)', fontSize: '14px' }}>
                  No se encontraron páginas
                </div>
              ) : (
                filteredPages.map((page, i) => (
                  <PageRow key={page.slug} page={page} isLast={i === filteredPages.length - 1} />
                ))
              )}
            </div>
          </div>
        </div>
      </WikiLayout>

      {/* Floating buttons */}
      {user.role === 'admin' ? (
        <MessageButton onClick={() => setMessagesOpen(true)} isDM={true} />
      ) : (
        <>
          <NotesButton onClick={() => setNotesOpen(true)} />
          <MessageButton onClick={() => setMessagesOpen(true)} unreadCount={unreadCount} />
        </>
      )}

      {/* Panels */}
      {user.role === 'admin' ? (
        <DMMessenger isOpen={messagesOpen} onClose={() => setMessagesOpen(false)} />
      ) : (
        <>
          <NotesPanel username={user.username} isOpen={notesOpen} onClose={() => setNotesOpen(false)} />
          <PlayerMessenger
            username={user.username}
            isOpen={messagesOpen}
            onClose={() => {
              setMessagesOpen(false);
              loadUnreadCount(user.username);
            }}
          />
        </>
      )}
    </>
  );
}
